class LRUCache
  def initialize(capacity)
    @capacity = capacity
    @store = {}
  end

  def get(key)
    return unless @store.key?(key)

    @store[key] = @store.delete(key)
  end

  def set(key, value)
    @store.delete(key)
    @store[key] = value
    @store.delete(@store.first[0]) if @store.size > @capacity
    value
  end
end
